import 'dart:io';
import 'package:flutter/material.dart';
import 'package:image_picker/image_picker.dart';
import 'package:supabase_flutter/supabase_flutter.dart';

const brand = Color(0xFF176B4D);
const ink = Color(0xFF17231D);
const canvas = Color(0xFFF6F8F5);

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  // Configure Supabase using --dart-define before enabling cloud features.
  const url = String.fromEnvironment('SUPABASE_URL');
  const anonKey = String.fromEnvironment('SUPABASE_ANON_KEY');
  if (url.isNotEmpty && anonKey.isNotEmpty) {
    await Supabase.initialize(url: url, anonKey: anonKey);
  }
  runApp(const LandMetricsApp());
}

class LandMetricsApp extends StatelessWidget {
  const LandMetricsApp({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(
    title: 'LAND METRICS', debugShowCheckedModeBanner: false,
    theme: ThemeData(useMaterial3: true, scaffoldBackgroundColor: canvas,
      colorScheme: ColorScheme.fromSeed(seedColor: brand),
      appBarTheme: const AppBarTheme(backgroundColor: canvas, foregroundColor: ink),
      inputDecorationTheme: InputDecorationTheme(filled: true, fillColor: Colors.white,
        border: OutlineInputBorder(borderRadius: BorderRadius.circular(14), borderSide: BorderSide.none))),
    home: const HomePage(),
  );
}

class HomePage extends StatefulWidget { const HomePage({super.key}); @override State<HomePage> createState()=>_HomePageState(); }
class _HomePageState extends State<HomePage> {
  int tab = 0;
  final ads = <AdListing>[];
  @override Widget build(BuildContext context) {
    final pages = [ExplorePage(ads: ads, onCreate: _createAd), const SavedPage(), const ProfilePage()];
    return Scaffold(appBar: AppBar(title: const Row(children:[Icon(Icons.landscape_rounded,color:brand,size:30), SizedBox(width:9), Text('LAND ',style:TextStyle(fontWeight:FontWeight.w900,letterSpacing:1.2)),Text('METRICS',style:TextStyle(fontWeight:FontWeight.w900,color:brand,letterSpacing:1.2))]), actions:[IconButton(onPressed:_createAd,icon:const Icon(Icons.add_circle_outline),tooltip:'Create advertisement')]),
      body: pages[tab], bottomNavigationBar: NavigationBar(selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v), destinations:const [NavigationDestination(icon:Icon(Icons.explore_outlined),selectedIcon:Icon(Icons.explore),label:'Explore'),NavigationDestination(icon:Icon(Icons.bookmark_border),selectedIcon:Icon(Icons.bookmark),label:'Saved'),NavigationDestination(icon:Icon(Icons.person_outline),selectedIcon:Icon(Icons.person),label:'Profile')]),
      floatingActionButton: tab==0 ? FloatingActionButton.extended(onPressed:_createAd,backgroundColor:brand,foregroundColor:Colors.white,icon:const Icon(Icons.campaign_outlined),label:const Text('Post an ad')) : null);
  }
  Future<void> _createAd() async { final result=await Navigator.push<AdListing>(context,MaterialPageRoute(builder:(_)=>const CreateAdPage())); if(result!=null&&mounted){setState(()=>ads.insert(0,result));ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Ad added to your preview feed. Connect Supabase to publish it online.')));} }
}

class AdListing { final String title,description,location,price; final File? image; AdListing({required this.title,required this.description,required this.location,required this.price,this.image}); }

