class CreateAdPage extends StatefulWidget {const CreateAdPage({super.key});@override State<CreateAdPage> createState()=>_CreateAdPageState();}
class _CreateAdPageState extends State<CreateAdPage>{final form=GlobalKey<FormState>();final title=TextEditingController(),description=TextEditingController(),location=TextEditingController(),price=TextEditingController();File? image;bool busy=false;Future<void> pick()async{final x=await ImagePicker().pickImage(source:ImageSource.gallery,imageQuality:85,maxWidth:1800);if(x!=null)setState(()=>image=File(x.path));}Future<void> submit()async{if(!(form.currentState?.validate()??false))return;setState(()=>busy=true);try{final url=const String.fromEnvironment('SUPABASE_URL');final key=const String.fromEnvironment('SUPABASE_ANON_KEY');if(image!=null&&url.isNotEmpty&&key.isNotEmpty){final client=Supabase.instance.client;final name='ad_${DateTime.now().millisecondsSinceEpoch}_${image!.path.split('/').last}';await client.storage.from('ad-images').upload(name,image!);final publicUrl=client.storage.from('ad-images').getPublicUrl(name);await client.from('advertisements').insert({'title':title.text.trim(),'description':description.text.trim(),'location':location.text.trim(),'price':price.text.trim(),'image_url':publicUrl,'status':'pending'});}if(mounted)Navigator.pop(context,AdListing(title:title.text.trim(),description:description.text.trim(),location:location.text.trim(),price:price.text.trim(),image:image));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Cloud upload failed: $e. Check Supabase setup; your ad can still be previewed locally.')));if(mounted)Navigator.pop(context,AdListing(title:title.text.trim(),description:description.text.trim(),location:location.text.trim(),price:price.text.trim(),image:image));}finally{if(mounted)setState(()=>busy=false);}}@override void dispose(){title.dispose();description.dispose();location.dispose();price.dispose();super.dispose();}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Create an advertisement',style:TextStyle(fontWeight:FontWeight.w800))),body:Form(key:form,child:ListView(padding:const EdgeInsets.all(18),children:[const Text('Showcase your property',style:TextStyle(fontSize:24,fontWeight:FontWeight.w900)),const SizedBox(height:6),const Text('Add a great photo and clear details to help buyers discover your listing.'),const SizedBox(height:20),GestureDetector(onTap:pick,child:Container(height:210,decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(18),border:Border.all(color:brand.withValues(alpha:.35))),child:image==null?const Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(Icons.add_photo_alternate_outlined,size:45,color:brand),SizedBox(height:10),Text('Add photos for your ad',style:TextStyle(fontWeight:FontWeight.w800)),Text('Tap to choose an image from your device',style:TextStyle(color:Colors.black54))]):ClipRRect(borderRadius:BorderRadius.circular(18),child:Image.file(image!,fit:BoxFit.cover,width:double.infinity)))),const SizedBox(height:18),_field(title,'Ad headline',required:true),const SizedBox(height:12),_field(location,'Location',required:true),const SizedBox(height:12),_field(price,'Price (optional)'),const SizedBox(height:12),_field(description,'Description',lines:4),const SizedBox(height:22),SizedBox(height:52,child:FilledButton.icon(onPressed:busy?null:submit,style:FilledButton.styleFrom(backgroundColor:brand),icon:busy?const SizedBox(width:18,height:18,child:CircularProgressIndicator(strokeWidth:2,color:Colors.white)):const Icon(Icons.campaign_outlined),label:Text(busy?'Publishing…':'Preview and publish ad'))),const SizedBox(height:10),const Text('Note: online publishing requires Supabase configuration and an ad-images storage bucket.',textAlign:TextAlign.center,style:TextStyle(color:Colors.black54,fontSize:12))])));}
Widget _field(TextEditingController c,String label,{bool required=false,int lines=1})=>TextFormField(controller:c,maxLines:lines,validator:required?(v)=>(v==null||v.trim().isEmpty)?'Please enter $label'.toLowerCase():null:null,decoration:InputDecoration(labelText:label,alignLabelWithHint:lines>1));
